from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

from Team_Phoenix_Library import (
    phoenix_gyro_spin_turn_the_old_way,
    phoenix_gyro_straight,
    phoenix_gyro_turn,
)

# Set up.
cefmfce = 0
right_drive = Motor(Port.F, Direction.CLOCKWISE)
left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_attachment = Motor(Port.E, Direction.CLOCKWISE)
left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(left_drive, right_drive, 62.4, 90)


# The main program starts here.
drive_base.use_gyro(True)
right_attachment.run_angle(50, 75)
phoenix_gyro_straight(630, 300, 0, 1.5, drive_base, left_drive, right_drive)
left_attachment.run_angle(500, 400)
phoenix_gyro_turn(100, 60, 30, 90, 'right', drive_base)
wait(50)
print(drive_base.angle())
cefmfce = 90 - drive_base.angle()
phoenix_gyro_straight(320, 300, cefmfce, 1, drive_base, left_drive, right_drive)
phoenix_gyro_spin_turn_the_old_way(125, -65, 45, -90.5, 'left', drive_base, left_drive, right_drive)
wait(50)
print(drive_base.angle())
cefmfce = -90 - drive_base.angle()
phoenix_gyro_straight(61, 125, cefmfce, 1.5, drive_base, left_drive, right_drive)
right_attachment.run_angle(500, 3100)
drive_base.settings(straight_speed=140)
drive_base.straight(-140)
phoenix_gyro_spin_turn_the_old_way(125, -117, 45, -130, 'left', drive_base, left_drive, right_drive)
wait(50)
print(drive_base.angle())
cefmfce = -130 - drive_base.angle()
drive_base.straight(-65)
left_attachment.run_angle(50, -180)
drive_base.settings(straight_speed=600)
drive_base.straight(600)
